// Hash utilities
import { Sha256 } from "./sha-256.js";
// Conversion functions
export function base64UintArrayToBase64UrlHashString(ua) {
    return btoa(String.fromCharCode(...ua)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=*$/g, '');
}
export function base64ArrayBufferToBase64UrlHashString(ab) {
    return base64UintArrayToBase64UrlHashString(new Uint8Array(ab));
}
// Hashing functions
// Helper to get crypto.subtle, with fallback for Node.js environments
async function getSubtle() {
    // Try browser's globalThis.crypto.subtle first
    if (globalThis.crypto?.subtle) {
        return globalThis.crypto.subtle;
    }
    // For Node.js, try to get webcrypto.subtle
    // This will be tree-shaken out in browser builds since process.versions.node is defined as undefined
    if (typeof process !== 'undefined' && process.versions?.node) {
        try {
            const nodeCrypto = await import("crypto");
            return nodeCrypto.webcrypto?.subtle ?? nodeCrypto.subtle;
        }
        catch {
            return undefined;
        }
    }
    return undefined;
}
export async function base64UrlHashForArrayBuffer(buffer, signal = undefined) {
    try {
        const subtle = await getSubtle();
        if (subtle) {
            return base64ArrayBufferToBase64UrlHashString(await subtle.digest("SHA-256", buffer));
        }
        else {
            console.warn(`Unable to find crypto.subtle library (probably insecure context). Slow hashing method will be used instead`);
        }
    }
    catch (e) {
        // Insecure context can cause this to fail in the browser
        console.warn(`Exception searching for crypto.subtle library (probably insecure context). Slow hashing method will be used instead`, e);
    }
    // Desperate casting to try and find a way to hash the buffer
    const sha = new Sha256();
    if (buffer instanceof Uint8Array) {
        sha.update(buffer);
    }
    else if (buffer instanceof ArrayBuffer) {
        sha.update(new Uint8Array(buffer));
    }
    else if (buffer instanceof Buffer) {
        sha.update(new Uint8Array(buffer));
    }
    else {
        throw new Error(`crypto.subtle not defined and unexpected buffer type`);
    }
    return base64UintArrayToBase64UrlHashString(sha.digest());
}
export async function base64UrlHashForFile(file, signal = undefined) {
    try {
        return await base64UrlHashForArrayBuffer(await file.arrayBuffer());
    }
    catch (e) {
        // Large files can cause this to fail. For example, Chrome has a 2GB limit currently
        console.warn(`Unable to get arrayBuffer from file (probably browser limit). Slow streaming method will be used instead.`, e);
    }
    // Use the streaming interface instead (much slower)
    const sha = new Sha256();
    const reader = file.stream().getReader();
    let isDone = false;
    while (!isDone) {
        if (signal?.aborted) {
            throw new Error(`Operation aborted by caller`);
        }
        const { done, value } = await reader.read();
        if (value) {
            sha.update(value);
        }
        isDone = done;
    }
    return base64UintArrayToBase64UrlHashString(sha.digest());
}
export async function base64UrlHashForFilePath(path) {
    // This function is Node.js only - it will throw in browser environments
    if (typeof process === 'undefined' || !process.versions?.node) {
        throw new Error("base64UrlHashForFilePath is only available in Node.js environments");
    }
    const { promises: { pipeline } } = await import("stream");
    const { createHash } = await import("crypto");
    const { createReadStream } = await import("fs");
    const readable = createReadStream(path);
    const hash = createHash("sha256");
    await pipeline(readable, hash);
    return hash.digest("base64url");
}
